import{_ as r,c as a,o as t,a1 as o}from"./chunks/framework.DhXu_kq-.js";const p=JSON.parse('{"title":"靈 / Rei FAN LYRICS","description":"","frontmatter":{},"headers":[],"relativePath":"fan-made/other/rei.md","filePath":"fan-made/other/rei.md"}'),i={name:"fan-made/other/rei.md"};function s(n,e,h,m,l,b){return t(),a("div",null,e[0]||(e[0]=[o('<h1 id="靈-rei-fan-lyrics" tabindex="-1">靈 / Rei FAN LYRICS <a class="header-anchor" href="#靈-rei-fan-lyrics" aria-label="Permalink to &quot;靈 / Rei FAN LYRICS&quot;">​</a></h1><blockquote><p>原视频：<a href="https://www.youtube.com/watch?v=wlHoh-EGNGM" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=wlHoh-EGNGM</a><br> 此为《靈》的非官方填词</p></blockquote><hr><h2 id="lyrics-en" tabindex="-1">Lyrics (EN) <a class="header-anchor" href="#lyrics-en" aria-label="Permalink to &quot;Lyrics (EN)&quot;">​</a></h2><h3 id="intro" tabindex="-1">Intro <a class="header-anchor" href="#intro" aria-label="Permalink to &quot;Intro&quot;">​</a></h3><p><em>I&#39;ve become a Spring Shrine Maiden</em><br><em>Dressed in a robe, waving gohei</em><br><em>Villagers kneel at my feet and</em><br><em>Pray for a rain...</em></p><h3 id="verse-1" tabindex="-1">Verse 1 <a class="header-anchor" href="#verse-1" aria-label="Permalink to &quot;Verse 1&quot;">​</a></h3><p><em>Days before, they mocked and beat me</em><br><em>Blasphemers, adults and children</em><br><em>God forgives them for their sins and</em><br><em>Grants them rain, albeit a bit late</em></p><p><em>They bring us their priced possessions</em><br><em>Offering them and their prayers</em><br><em>No longer we live worse than they</em><br><em>Keeping up the lie of worship</em></p><h3 id="bridge-1" tabindex="-1">Bridge 1 <a class="header-anchor" href="#bridge-1" aria-label="Permalink to &quot;Bridge 1&quot;">​</a></h3><p><em>And we all know</em><br><em>That one day, lies</em><br><em>Become revealed at once</em><br><em>But that&#39;s the only way I can help</em></p><h3 id="verse-2" tabindex="-1">Verse 2 <a class="header-anchor" href="#verse-2" aria-label="Permalink to &quot;Verse 2&quot;">​</a></h3><p><em>After finishing the procedure again</em><br><em>People began asking if God really needs</em><br><em>Their offerings, so many every year</em><br><em>And they began asking if the God is real</em></p><p><em>&quot;You dare to show such disrespect?!</em><br><em>Is it another drought you seek?!</em><br><em>Hey! What are you staring at?</em><br><em>Before God angers, you all better step back!&quot;</em></p><h3 id="verse-3" tabindex="-1">Verse 3 <a class="header-anchor" href="#verse-3" aria-label="Permalink to &quot;Verse 3&quot;">​</a></h3><p><em>Years have passed since then, they began to wake up</em><br><em>Just a Mom and Dad wanted to leave this place behind</em><br><em>I wanted to do just one dance, most sincere one</em><br><em>That rain, it was mine.</em></p><p><em>People stood before our gates with torches in their hands</em><br><em>Demanding explanation for the lack of rains</em><br><em>Insolent fools, these people and their faith</em><br><em>How laughable.</em></p><h3 id="verse-4" tabindex="-1">Verse 4 <a class="header-anchor" href="#verse-4" aria-label="Permalink to &quot;Verse 4&quot;">​</a></h3><p><em>Mother begged them to spare me, snce</em><br><em>Spring Shrine Maiden didn&#39;t exist</em><br><em>Just one rain. What&#39;s so substantial.</em><br><em>Cloak gather as I&#39;m yelling</em></p><p><em>&quot;Silence! Your defilement is</em><br><em>A sin that&#39;s beyond forgiveness</em><br><em>The sky shall judge you!&quot; And, fearless</em><br><em>Stood my ground to their weapons</em></p><h3 id="bridge-2" tabindex="-1">Bridge 2 <a class="header-anchor" href="#bridge-2" aria-label="Permalink to &quot;Bridge 2&quot;">​</a></h3><p><em>Why should I be afraid of them?</em><br><em>Not since I&#39;ve become Haru-no-Miko</em><br><em>Have I feared anything at all</em><br><em>After all, I was never a shrine maiden</em><br><em>I, am the God.</em></p><p><em>Then, let me</em><br><em>Pray for thee</em><br><em>And for the rain you crave so desperately</em></p><h3 id="verse-5" tabindex="-1">Verse 5 <a class="header-anchor" href="#verse-5" aria-label="Permalink to &quot;Verse 5&quot;">​</a></h3><p><em>Rain has fallen, as they had asked for</em><br><em>They began praying to the God once more</em><br><em>Fools, these people. Rain, unstopping</em><br><em>Flooding everything that stood in its way</em></p><h3 id="outro" tabindex="-1">Outro <a class="header-anchor" href="#outro" aria-label="Permalink to &quot;Outro&quot;">​</a></h3><p><em>Now, they beg for its end</em><br><em>Blaming me, saying I&#39;m cursed instead</em><br><em>Seeking my death and demise</em><br><em>Lowly mortals, rain is nice...</em></p><hr><h2 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">中文翻译</p><h3 id="intro-1" tabindex="-1">Intro <a class="header-anchor" href="#intro-1" aria-label="Permalink to &quot;Intro&quot;">​</a></h3><p>我已化身为「春之巫女」<br> 身披法袍，挥舞御币<br> 村民们跪拜在我的脚下<br> 祈求着一场甘霖……</p><h3 id="verse-1-1" tabindex="-1">Verse 1 <a class="header-anchor" href="#verse-1-1" aria-label="Permalink to &quot;Verse 1&quot;">​</a></h3><p>几日之前，他们还对我极尽嘲讽与毒打<br> 这群亵渎者，无论大人还是孩童<br> 神明宽恕了他们的罪孽<br> 并赐予雨水，尽管来得迟了一些</p><p>他们带来了珍贵的财物<br> 献祭宝物与他们的祈祷<br> 我们不再过得比他们卑微<br> 只需要维持着这虚假的崇拜</p><h3 id="bridge-1-1" tabindex="-1">Bridge 1 <a class="header-anchor" href="#bridge-1-1" aria-label="Permalink to &quot;Bridge 1&quot;">​</a></h3><p>我们都深知<br> 总有一天，谎言<br> 会在一瞬间被揭穿<br> 但这是我唯一能帮上忙的方式</p><h3 id="verse-2-1" tabindex="-1">Verse 2 <a class="header-anchor" href="#verse-2-1" aria-label="Permalink to &quot;Verse 2&quot;">​</a></h3><p>当又一次完成仪式之后<br> 人们开始质问，神是否真的需要<br> 他们每年如此大量的供奉<br> 他们甚至开始质疑神是否真的存在</p><p>“尔等竟敢如此大不敬？！<br> 难道你们还想招致旱灾吗？！<br> 喂！看什么看？<br> 趁神明发怒之前，赶紧退下！”</p><h3 id="verse-3-1" tabindex="-1">Verse 3 <a class="header-anchor" href="#verse-3-1" aria-label="Permalink to &quot;Verse 3&quot;">​</a></h3><p>经年累月，人们开始觉醒<br> 只有父亲和母亲想要离开这个地方<br> 而我只想跳一支舞，这是我最诚挚的一支<br> 那场雨，是我唤来的。</p><p>人们手持火把伫立在门前<br> 逼问为何久旱无雨<br> 傲慢的蠢货，这群人与他们的信仰<br> 何其可笑。</p><h3 id="verse-4-1" tabindex="-1">Verse 4 <a class="header-anchor" href="#verse-4-1" aria-label="Permalink to &quot;Verse 4&quot;">​</a></h3><p>母亲乞求他们放过我，因为<br> 所谓的「春之巫女」根本就不存在<br> 不过是一场雨，有什么大不了的<br> 我裹紧长袍，高声怒喝：</p><p>“肃静！你们的污秽<br> 是无法宽恕的罪孽<br> 上天将审判你们！”<br> 面对他们的武器，我毫无惧色，寸步不让</p><h3 id="bridge-2-1" tabindex="-1">Bridge 2 <a class="header-anchor" href="#bridge-2-1" aria-label="Permalink to &quot;Bridge 2&quot;">​</a></h3><p>我为何要怕他们？<br> 自从成为「春之巫女」以来<br> 我便未曾畏惧过任何事物<br> 毕竟，我从未是什么巫女<br> 我，即是神明。</p><p>既然如此，那就让我<br> 为尔等祈祷<br> 赐予你们如此渴求的雨水吧</p><h3 id="verse-5-1" tabindex="-1">Verse 5 <a class="header-anchor" href="#verse-5-1" aria-label="Permalink to &quot;Verse 5&quot;">​</a></h3><p>雨降下了，正如他们所愿<br> 他们再次开始向神祈祷<br> 这群愚民。雨水无休无止<br> 淹没了一切阻挡之物</p><h3 id="outro-1" tabindex="-1">Outro <a class="header-anchor" href="#outro-1" aria-label="Permalink to &quot;Outro&quot;">​</a></h3><p>如今，他们乞求雨停<br> 反而怪罪于我，称我是受诅咒之人<br> 妄图置我于死地<br> 卑微的凡人啊，这雨甚是美妙……</p></div>',30)]))}const c=r(i,[["render",s]]);export{p as __pageData,c as default};
